#include <vector>
#include <string>
#include <unordered_set>
#include <unordered_map>
#include <queue>

class Solution {
public:
    std::vector<std::string> findAllRecipes(std::vector<std::string>& recipes, std::vector<std::vector<std::string>>& ingredients, std::vector<std::string>& supplies) {
        std::unordered_set<std::string> supplySet(supplies.begin(), supplies.end());
        std::unordered_map<std::string, std::vector<std::string>> adj;
        std::unordered_map<std::string, int> inDegree;

        for (int i = 0; i < (int)recipes.size(); ++i) {
            const std::string& r = recipes[i];
            for (const auto& ing : ingredients[i]) {
                if (!supplySet.count(ing)) {
                    adj[ing].push_back(r);
                    inDegree[r]++;
                }
            }
        }

        std::queue<std::string> q;
        for (const auto& r : recipes) {
            if (inDegree[r] == 0) q.push(r);
        }

        std::vector<std::string> ans;
        while (!q.empty()) {
            std::string curr = q.front();
            q.pop();
            ans.push_back(curr);

            for (const auto& nxt : adj[curr]) {
                if (--inDegree[nxt] == 0) {
                    q.push(nxt);
                }
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public List<String> findAllRecipes(String[] recipes, List<List<String>> ingredients, String[] supplies) {
        Set<String> supplySet = new HashSet<>(Arrays.asList(supplies));
        Map<String, List<String>> adj = new HashMap<>();
        Map<String, Integer> inDegree = new HashMap<>();

        for (int i = 0; i < recipes.length; i++) {
            String r = recipes[i];
            for (String ing : ingredients.get(i)) {
                if (!supplySet.contains(ing)) {
                    adj.computeIfAbsent(ing, k -> new ArrayList<>()).add(r);
                    inDegree.put(r, inDegree.getOrDefault(r, 0) + 1);
                }
            }
        }

        Deque<String> queue = new ArrayDeque<>();
        for (String r : recipes) {
            if (inDegree.getOrDefault(r, 0) == 0) {
                queue.offer(r);
            }
        }

        List<String> ans = new ArrayList<>();
        while (!queue.isEmpty()) {
            String curr = queue.poll();
            ans.add(curr);

            if (adj.containsKey(curr)) {
                for (String dep : adj.get(curr)) {
                    int deg = inDegree.get(dep) - 1;
                    inDegree.put(dep, deg);
                    if (deg == 0) queue.offer(dep);
                }
            }
        }
        return ans;
    }
}

/**
 * @param {string[]} recipes
 * @param {string[][]} ingredients
 * @param {string[]} supplies
 * @return {string[]}
 */
var findAllRecipes = function(recipes, ingredients, supplies) {
    const supplySet = new Set(supplies);
    const adj = new Map();
    const inDegree = new Map();

    for (let i = 0; i < recipes.length; i++) {
        const r = recipes[i];
        for (const ing of ingredients[i]) {
            if (!supplySet.has(ing)) {
                if (!adj.has(ing)) adj.set(ing, []);
                adj.get(ing).push(r);
                inDegree.set(r, (inDegree.get(r) || 0) + 1);
            }
        }
    }

    const queue = [];
    for (const r of recipes) {
        if (!inDegree.has(r) || inDegree.get(r) === 0) {
            queue.push(r);
        }
    }

    const ans = [];
    let head = 0;
    while (head < queue.length) {
        const curr = queue[head++];
        ans.push(curr);

        const deps = adj.get(curr) || [];
        for (const dep of deps) {
            const deg = inDegree.get(dep) - 1;
            inDegree.set(dep, deg);
            if (deg === 0) queue.push(dep);
        }
    }
    return ans;
};
